  "sourcesContent": ["/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nexport const VencordFragment = /* #__PURE__*/ Symbol.for(\"react.fragment\");\nexport let VencordCreateElement =\n    (...args) => (VencordCreateElement = Vencord.Webpack.Common.React.createElement)(...args);\n", "/* the profile popout badge container(s) */\n[class*=\"profile_\"] [class*=\"tags_\"] [class*=\"container_\"] {\n    /* Discord has gap set to 2px instead of 1px, which causes the 12th badge to wrap to a new line. */\n    gap: 1px;\n}", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nexport function makeLazy<T>(factory: () => T, attempts = 5): () => T {\n    let tries = 0;\n    let cache: T;\n    return () => {\n        if (cache === undefined && attempts > tries++) {\n            cache = factory();\n            if (cache === undefined && attempts === tries)\n                console.error(\"Lazy factory failed:\", factory);\n        }\n        return cache;\n    };\n}\n\n// Proxies demand that these properties be unmodified, so proxyLazy\n// will always return the function default for them.\nconst unconfigurable = [\"arguments\", \"caller\", \"prototype\"];\n\nconst handler: ProxyHandler<any> = {};\n\nexport const SYM_LAZY_GET = Symbol.for(\"vencord.lazy.get\");\nexport const SYM_LAZY_CACHED = Symbol.for(\"vencord.lazy.cached\");\n\nfor (const method of [\n    \"apply\",\n    \"construct\",\n    \"defineProperty\",\n    \"deleteProperty\",\n    \"getOwnPropertyDescriptor\",\n    \"getPrototypeOf\",\n    \"has\",\n    \"isExtensible\",\n    \"ownKeys\",\n    \"preventExtensions\",\n    \"set\",\n    \"setPrototypeOf\"\n]) {\n    handler[method] =\n        (target: any, ...args: any[]) => Reflect[method](target[SYM_LAZY_GET](), ...args);\n}\n\nhandler.ownKeys = target => {\n    const v = target[SYM_LAZY_GET]();\n    const keys = Reflect.ownKeys(v);\n    for (const key of unconfigurable) {\n        if (!keys.includes(key)) keys.push(key);\n    }\n    return keys;\n};\n\nhandler.getOwnPropertyDescriptor = (target, p) => {\n    if (typeof p === \"string\" && unconfigurable.includes(p))\n        return Reflect.getOwnPropertyDescriptor(target, p);\n\n    const descriptor = Reflect.getOwnPropertyDescriptor(target[SYM_LAZY_GET](), p);\n\n    if (descriptor) Object.defineProperty(target, p, descriptor);\n    return descriptor;\n};\n\n/**\n * Wraps the result of {@link makeLazy} in a Proxy you can consume as if it wasn't lazy.\n * On first property access, the lazy is evaluated\n * @param factory lazy factory\n * @param attempts how many times to try to evaluate the lazy before giving up\n * @returns Proxy\n *\n * Note that the example below exists already as an api, see {@link findByPropsLazy}\n * @example const mod = proxyLazy(() => findByProps(\"blah\")); console.log(mod.blah);\n */\nexport function proxyLazy<T>(factory: () => T, attempts = 5, isChild = false): T {\n    let isSameTick = true;\n    if (!isChild)\n        setTimeout(() => isSameTick = false, 0);\n\n    let tries = 0;\n    const proxyDummy = Object.assign(function () { }, {\n        [SYM_LAZY_CACHED]: void 0 as T | undefined,\n        [SYM_LAZY_GET]() {\n            if (!proxyDummy[SYM_LAZY_CACHED] && attempts > tries++) {\n                proxyDummy[SYM_LAZY_CACHED] = factory();\n                if (!proxyDummy[SYM_LAZY_CACHED] && attempts === tries)\n                    console.error(\"Lazy factory failed:\", factory);\n            }\n            return proxyDummy[SYM_LAZY_CACHED];\n        }\n    });\n\n    return new Proxy(proxyDummy, {\n        ...handler,\n        get(target, p, receiver) {\n            if (p === SYM_LAZY_CACHED || p === SYM_LAZY_GET)\n                return Reflect.get(target, p, receiver);\n\n            // if we're still in the same tick, it means the lazy was immediately used.\n            // thus, we lazy proxy the get access to make things like destructuring work as expected\n            // meow here will also be a lazy\n            // `const { meow } = findByPropsLazy(\"meow\");`\n            if (!isChild && isSameTick)\n                return proxyLazy(\n                    () => Reflect.get(target[SYM_LAZY_GET](), p, receiver),\n                    attempts,\n                    true\n                );\n            const lazyTarget = target[SYM_LAZY_GET]();\n            if (typeof lazyTarget === \"object\" || typeof lazyTarget === \"function\") {\n                return Reflect.get(lazyTarget, p, receiver);\n            }\n            throw new Error(\"proxyLazy called on a primitive value\");\n        }\n    }) as any;\n}\n", "/*\n * Vencord, a Discord client mod\n * Copyright (c) 2023 Vendicated and contributors\n * SPDX-License-Identifier: GPL-3.0-or-later\n */\n\nimport type { ComponentType } from \"react\";\n\nimport { makeLazy } from \"./lazy\";\n\nconst NoopComponent = () => null;\n\nexport type LazyComponentWrapper<ComponentType> = ComponentType & { $$vencordGetWrappedComponent(): ComponentType; };\n\n/**\n * A lazy component. The factory method is called on first render.\n * @param factory Function returning a Component\n * @param attempts How many times to try to get the component before giving up\n * @returns Result of factory function\n */\nexport function LazyComponent<T extends object = any>(factory: () => ComponentType<T>, attempts = 5): LazyComponentWrapper<ComponentType<T>> {\n    const get = makeLazy(factory, attempts);\n    const LazyComponent = (props: T) => {\n        const Component = get() ?? NoopComponent;\n        return <Component {...props} />;\n    };\n\n    LazyComponent.$$vencordGetWrappedComponent = get;\n\n    return LazyComponent;\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nexport class Logger {\n    /**\n     * Returns the console format args for a title with the specified background colour and black text\n     * @param color Background colour\n     * @param title Text\n     * @returns Array. Destructure this into {@link Logger}.errorCustomFmt or console.log\n     *\n     * @example logger.errorCustomFmt(...Logger.makeTitleElements(\"white\", \"Hello\"), \"World\");\n     */\n    static makeTitle(color: string, title: string): [string, ...string[]] {\n        return [\"%c %c %s \", \"\", `background: ${color}; color: black; font-weight: bold; border-radius: 5px;`, title];\n    }\n\n    constructor(public name: string, public color: string = \"white\") { }\n\n    private _log(level: \"log\" | \"error\" | \"warn\" | \"info\" | \"debug\", levelColor: string, args: any[], customFmt = \"\") {\n        if (IS_REPORTER && IS_WEB && !IS_VESKTOP) {\n            console[level](\"[Vencord]\", this.name + \":\", ...args);\n            return;\n        }\n\n        console[level](\n            `%c Vencord %c %c ${this.name} ${customFmt}`,\n            `background: ${levelColor}; color: black; font-weight: bold; border-radius: 5px;`,\n            \"\",\n            `background: ${this.color}; color: black; font-weight: bold; border-radius: 5px;`\n            , ...args\n        );\n    }\n\n    public log(...args: any[]) {\n        this._log(\"log\", \"#a6d189\", args);\n    }\n\n    public info(...args: any[]) {\n        this._log(\"info\", \"#a6d189\", args);\n    }\n\n    public error(...args: any[]) {\n        this._log(\"error\", \"#e78284\", args);\n    }\n\n    public errorCustomFmt(fmt: string, ...args: any[]) {\n        this._log(\"error\", \"#e78284\", args, fmt);\n    }\n\n    public warn(...args: any[]) {\n        this._log(\"warn\", \"#e5c890\", args);\n    }\n\n    public debug(...args: any[]) {\n        this._log(\"debug\", \"#eebebe\", args);\n    }\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nimport type { MapValue } from \"type-fest/source/entry\";\n\nexport type Style = MapValue<typeof VencordStyles>;\n\nexport const styleMap = window.VencordStyles ??= new Map();\n\nexport function requireStyle(name: string) {\n    const style = styleMap.get(name);\n    if (!style) throw new Error(`Style \"${name}\" does not exist`);\n    return style;\n}\n\n/**\n * A style's name can be obtained from importing a stylesheet with `?managed` at the end of the import\n * @param name The name of the style\n * @returns `false` if the style was already enabled, `true` otherwise\n * @example\n * import pluginStyle from \"./plugin.css?managed\";\n *\n * // Inside some plugin method like \"start()\" or \"[option].onChange()\"\n * enableStyle(pluginStyle);\n */\nexport function enableStyle(name: string) {\n    const style = requireStyle(name);\n\n    if (style.dom?.isConnected)\n        return false;\n\n    if (!style.dom) {\n        style.dom = document.createElement(\"style\");\n        style.dom.dataset.vencordName = style.name;\n    }\n    compileStyle(style);\n\n    document.head.appendChild(style.dom);\n    return true;\n}\n\n/**\n * @param name The name of the style\n * @returns `false` if the style was already disabled, `true` otherwise\n * @see {@link enableStyle} for info on getting the name of an imported style\n */\nexport function disableStyle(name: string) {\n    const style = requireStyle(name);\n    if (!style.dom?.isConnected)\n        return false;\n\n    style.dom.remove();\n    style.dom = null;\n    return true;\n}\n\n/**\n * @param name The name of the style\n * @returns `true` in most cases, may return `false` in some edge cases\n * @see {@link enableStyle} for info on getting the name of an imported style\n */\nexport const toggleStyle = (name: string) => isStyleEnabled(name) ? disableStyle(name) : enableStyle(name);\n\n/**\n * @param name The name of the style\n * @returns Whether the style is enabled\n * @see {@link enableStyle} for info on getting the name of an imported style\n */\nexport const isStyleEnabled = (name: string) => requireStyle(name).dom?.isConnected ?? false;\n\n/**\n * Sets the variables of a style\n * ```ts\n * // -- plugin.ts --\n * import pluginStyle from \"./plugin.css?managed\";\n * import { setStyleVars } from \"@api/Styles\";\n * import { findByPropsLazy } from \"@webpack\";\n * const classNames = findByPropsLazy(\"thin\", \"scrollerBase\"); // { thin: \"thin-31rlnD scrollerBase-_bVAAt\", ... }\n *\n * // Inside some plugin method like \"start()\"\n * setStyleClassNames(pluginStyle, classNames);\n * enableStyle(pluginStyle);\n * ```\n * ```scss\n * // -- plugin.css --\n * .plugin-root [--thin]::-webkit-scrollbar { ... }\n * ```\n * ```scss\n * // -- final stylesheet --\n * .plugin-root .thin-31rlnD.scrollerBase-_bVAAt::-webkit-scrollbar { ... }\n * ```\n * @param name The name of the style\n * @param classNames An object where the keys are the variable names and the values are the variable values\n * @param recompile Whether to recompile the style after setting the variables, defaults to `true`\n * @see {@link enableStyle} for info on getting the name of an imported style\n */\nexport const setStyleClassNames = (name: string, classNames: Record<string, string>, recompile = true) => {\n    const style = requireStyle(name);\n    style.classNames = classNames;\n    if (recompile && isStyleEnabled(style.name))\n        compileStyle(style);\n};\n\n/**\n * Updates the stylesheet after doing the following to the sourcecode:\n *   - Interpolate style classnames\n * @param style **_Must_ be a style with a DOM element**\n * @see {@link setStyleClassNames} for more info on style classnames\n */\nexport const compileStyle = (style: Style) => {\n    if (!style.dom) throw new Error(\"Style has no DOM element\");\n\n    style.dom.textContent = style.source\n        .replace(/\\[--(\\w+)\\]/g, (match, name) => {\n            const className = style.classNames[name];\n            return className ? classNameToSelector(className) : match;\n        });\n};\n\n/**\n * @param name The classname\n * @param prefix A prefix to add each class, defaults to `\"\"`\n * @return A css selector for the classname\n * @example\n * classNameToSelector(\"foo bar\") // => \".foo.bar\"\n */\nexport const classNameToSelector = (name: string, prefix = \"\") => name.split(\" \").map(n => `.${prefix}${n}`).join(\"\");\n\ntype ClassNameFactoryArg = string | string[] | Record<string, unknown> | false | null | undefined | 0 | \"\";\n/**\n * @param prefix The prefix to add to each class, defaults to `\"\"`\n * @returns A classname generator function\n * @example\n * const cl = classNameFactory(\"plugin-\");\n *\n * cl(\"base\", [\"item\", \"editable\"], { selected: null, disabled: true })\n * // => \"plugin-base plugin-item plugin-editable plugin-disabled\"\n */\nexport const classNameFactory = (prefix: string = \"\") => (...args: ClassNameFactoryArg[]) => {\n    const classNames = new Set<string>();\n    for (const arg of args) {\n        if (arg && typeof arg === \"string\") classNames.add(arg);\n        else if (Array.isArray(arg)) arg.forEach(name => classNames.add(name));\n        else if (arg && typeof arg === \"object\") Object.entries(arg).forEach(([name, value]) => value && classNames.add(name));\n    }\n    return Array.from(classNames, name => prefix + name).join(\" \");\n};\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2023 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nimport { classNameFactory } from \"@api/Styles\";\n\nconst marginCls = classNameFactory(\"vc-margin-\");\n\nconst Directions = [\"top\", \"bottom\", \"left\", \"right\"] as const;\nconst Sizes = [8, 16, 20] as const;\n\nexport type MarginDirection = (typeof Directions)[number];\nexport type MarginSize = (typeof Sizes)[number];\n\nexport const Margins: Record<`${MarginDirection}${MarginSize}`, string> = {} as any;\n\nexport function generateMarginCss() {\n    let css = \"\";\n\n    for (const direction of Directions) {\n        for (const size of Sizes) {\n            const cl = marginCls(`${direction}-${size}`);\n            Margins[`${direction}${size}`] = cl;\n            css += `.${cl}{margin-${direction}:${size}px;}`;\n        }\n    }\n\n    return css;\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2023 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\n// TODO: Migrate all usages from utils to components\nexport { Margins } from \"@components/margins\";\n", ".vc-error-card {\n    padding: 2em;\n    background-color: #e7828430;\n    border: 1px solid #e78284;\n    border-radius: 5px;\n    color: var(--text-default, white);\n\n    & a:hover {\n        text-decoration: underline;\n    }\n}\n", "// xxHash64 implementation in JavaScript\n//\n// Licensed under MIT License\n//\n// Copyright 2019-2020, Yann Collet <github.com/Cyan4973>\n// Copyright 2016, Pierre Curto <github.com/pierrec>\n// Copyright 2019, Daniel Lo Nigro <github.com/Daniel15>\n// Copyright 2021, intrnl <github.com/intrnl>\n\nconst PRIME64_1 = 11400714785074694791n;\nconst PRIME64_2 = 14029467366897019727n;\nconst PRIME64_3 = 1609587929392839161n;\nconst PRIME64_4 = 9650029242287828579n;\nconst PRIME64_5 = 2870177450012600261n;\n\nconst BITS = 64n;\nconst BITMASK = 2n ** BITS - 1n;\n\nconst encoder = new TextEncoder();\n\n\nfunction bitsToBigInt (a00, a16, a32, a48) {\n\treturn (\n\t\t(BigInt(a00)) |\n\t\t(BigInt(a16) << 16n) |\n\t\t(BigInt(a32) << 32n) |\n\t\t(BigInt(a48) << 48n)\n\t);\n}\n\nfunction memoryToBigInt(memory, offset) {\n\treturn (\n\t\t(BigInt(memory[offset])) |\n\t\t(BigInt(memory[offset+1]) << 8n) |\n\t\t(BigInt(memory[offset+2]) << 16n) |\n\t\t(BigInt(memory[offset+3]) << 24n) |\n\t\t(BigInt(memory[offset+4]) << 32n) |\n\t\t(BigInt(memory[offset+5]) << 40n) |\n\t\t(BigInt(memory[offset+6]) << 48n) |\n\t\t(BigInt(memory[offset+7]) << 56n)\n\t);\n}\n\nfunction rotl (value, rotation) {\n\treturn (\n\t\t((value << rotation) & BITMASK) |\n\t\t(value >> (BITS - rotation))\n\t);\n}\n\nfunction trunc (value) {\n\treturn BigInt.asUintN(64, value);\n}\n\n\nexport class XXH64 {\n\t#seed;\n\t#v1;\n\t#v2;\n\t#v3;\n\t#v4;\n\n\t#memory;\n\n\t#len;\n\t#memsize;\n\n\tconstructor (seed = 0) {\n\t\tthis.reset(seed);\n\t}\n\n\treset (seed = this.#seed) {\n\t\tthis.#seed = BigInt.asUintN(32, BigInt(seed));\n\t\tthis.#v1 = trunc(this.#seed + PRIME64_1 + PRIME64_2);\n\t\tthis.#v2 = trunc(this.#seed + PRIME64_2);\n\t\tthis.#v3 = this.#seed;\n\t\tthis.#v4 = trunc(this.#seed - PRIME64_1);\n\n\t\tthis.#memory = null;\n\n\t\tthis.#len = 0;\n\t\tthis.#memsize = 0;\n\n\t\treturn this;\n\t}\n\n\tupdate (input) {\n\t\tif (typeof input === 'string') {\n\t\t\tinput = encoder.encode(input);\n\t\t}\n\n\t\tlet p = 0;\n\t\tlet len = input.length;\n\t\tlet bEnd = p + len;\n\n\t\tif (len === 0) {\n\t\t\treturn this;\n\t\t}\n\n\t\tthis.#len += len;\n\n\t\tif (this.#memsize === 0) {\n\t\t\tthis.#memory = new Uint8Array(32);\n\t\t}\n\n\t\tif (this.#memsize + len < 32) {\n\t\t\tthis.#memory.set(input.subarray(0, len), this.#memsize);\n\n\t\t\tthis.#memsize += len;\n\t\t\treturn this;\n\t\t}\n\n\t\tif (this.#memsize > 0) {\n\t\t\tthis.#memory.set(input.subarray(0, 32 - this.#memsize), this.#memsize);\n\n\t\t\tlet p64 = 0;\n\t\t\tlet other;\n\n\t\t\tother = memoryToBigInt(this.#memory, p64);\n\t\t\tthis.#v1 = trunc(rotl(trunc(this.#v1 + other * PRIME64_2), 31n) * PRIME64_1);\n\n\t\t\tp64 += 8\n\t\t\tother = memoryToBigInt(this.memory, p64)\n\t\t\tthis.#v2 = trunc(rotl(trunc(this.#v2 + other * PRIME64_2), 31n) * PRIME64_1);\n\n\t\t\tp64 += 8\n\t\t\tother = memoryToBigInt(this.memory, p64)\n\t\t\tthis.#v3 = trunc(rotl(trunc(this.#v3 + other * PRIME64_2), 31n) * PRIME64_1);\n\n\t\t\tp64 += 8\n\t\t\tother = memoryToBigInt(this.memory, p64)\n\t\t\tthis.#v4 = trunc(rotl(trunc(this.#v4 + other * PRIME64_2), 31n) * PRIME64_1);\n\n\t\t\tp += 32 - this.#memsize;\n\t\t\tthis.#memsize = 0;\n\t\t}\n\n\t\tif (p <= bEnd - 32) {\n\t\t\tconst limit = bEnd - 32;\n\n\t\t\tdo {\n\t\t\t\tlet other;\n\n\t\t\t\tother = memoryToBigInt(input, p)\n\t\t\t\tthis.#v1 = trun