egister a new badge with the Badges API\n * @param badge The badge to register\n */\nexport function addProfileBadge(badge: ProfileBadge) {\n    badge.component &&= ErrorBoundary.wrap(badge.component, { noop: true });\n    Badges.add(badge);\n}\n\n/**\n * Unregister a badge from the Badges API\n * @param badge The badge to remove\n */\nexport function removeProfileBadge(badge: ProfileBadge) {\n    return Badges.delete(badge);\n}\n\n/**\n * Inject badges into the profile badges array.\n * You probably don't need to use this.\n */\nexport function _getBadges(args: BadgeUserArgs) {\n    const badges = [] as ProfileBadge[];\n    for (const badge of Badges) {\n        if (badge.shouldShow && !badge.shouldShow(args)) {\n            continue;\n        }\n\n        const b = badge.getBadges\n            ? badge.getBadges(args).map(badge => ({\n                ...args,\n                ...badge,\n                component: badge.component && ErrorBoundary.wrap(badge.component, { noop: true })\n            }))\n            : [{ ...args, ...badge }];\n\n        if (badge.position === BadgePosition.START) {\n            badges.unshift(...b);\n        } else {\n            badges.push(...b);\n        }\n    }\n\n    const donorBadges = BadgeAPIPlugin.getDonorBadges(args.userId);\n    if (donorBadges) {\n        badges.unshift(\n            ...donorBadges.map(badge => ({\n                ...args,\n                ...badge,\n            }))\n        );\n    }\n\n    return badges;\n}\n\nexport interface BadgeUserArgs {\n    userId: string;\n    guildId: string;\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nimport type { React } from \"@webpack/common\";\n\nexport function Flex(props: React.PropsWithChildren<{\n    flexDirection?: React.CSSProperties[\"flexDirection\"];\n    style?: React.CSSProperties;\n    className?: string;\n} & React.HTMLProps<HTMLDivElement>>) {\n    props.style ??= {};\n    props.style.display = \"flex\";\n    // TODO(ven): Remove me, what was I thinking??\n    props.style.gap ??= \"1em\";\n    props.style.flexDirection ||= props.flexDirection;\n    delete props.flexDirection;\n    return (\n        <div {...props}>\n            {props.children}\n        </div>\n    );\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nimport { classes } from \"@utils/misc\";\nimport { SVGProps } from \"react\";\n\nexport function Heart(props: SVGProps<SVGSVGElement>) {\n    return (\n        <svg\n            aria-hidden=\"true\"\n            viewBox=\"0 0 16 16\"\n            height=\"16