 {\n    return (\n        <Button\n            {...props}\n            look={look}\n            color={color}\n            onClick={() => VencordNative.native.openExternal(\"https://github.com/sponsors/Vendicated\")}\n            className=\"vc-donate-button\"\n        >\n            <Heart />\n            Donate\n        </Button>\n    );\n}\n", ".vc-settings-tab-bar {\n    margin-top: 20px;\n    margin-bottom: 10px;\n    border-bottom: 1px solid var(--border-subtle);\n}\n\n.vc-settings-tab-bar-item {\n    margin-right: 32px;\n    padding-bottom: 16px;\n    margin-bottom: -2px;\n}\n\n.vc-settings-donate {\n    display: flex;\n    flex-direction: row;\n}\n\n.vc-settings-card {\n    padding: 1em;\n    margin-bottom: 1em;\n}\n\n.vc-warning-card {\n    padding: 1em;\n    background: var(--info-warning-background);\n    border: 1px solid var(--info-warning-foreground);\n    color: var(--info-warning-foreground);\n}\n\n.vc-backup-restore-card {\n    background-color: var(--info-warning-background);\n    border-color: var(--info-warning-foreground);\n    color: var(--info-warning-foreground);\n}\n\n.vc-settings-theme-links {\n    /* Needed to fix bad themes that hide certain textarea elements for whatever eldritch reason */\n    display: inline-block !important;\n    color: var(--text-default) !important;\n    padding: 0.5em 1em;\n    border: 1px solid var(--input-border);\n    max-height: unset;\n    background-color: transparent;\n    box-sizing: border-box;\n    resize: none;\n    width: 100%;\n    font-size: 1em;\n    line-height: 2em;\n    white-space: nowrap;\n}\n\n.vc-settings-theme-links::placeholder {\n    color: var(--text-muted) !important;\n}\n\n.vc-settings-theme-links:focus {\n    background-color: var(--background-base-lowest);\n}\n\n.vc-cloud-settings-sync-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    grid-gap: 1em;\n}\n\n.vc-cloud-erase-data-danger-btn {\n    color: var(--white-500);\n    background-color: var(--button-danger-background);\n}\n\n.vc-updater-modal {\n    padding: 1.5em !important;\n}\n\n.vc-updater-modal-close-button {\n    float: right;\n}", "export default \"efe6f5c\"", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2023 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nexport function relaunch() {\n    if (IS_DISCORD_DESKTOP)\n        window.DiscordNative.app.relaunch();\n    else\n        window.VesktopNative.app.relaunch();\n}\n\nexport function showItemInFolder(path: string) {\n    if (IS_DISCORD_DESKTOP)\n        window.DiscordNative.fileManager.showItemInFolder(path);\n    else\n        window.VesktopNative.fileManager.showItemInFolder(path);\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nimport gitHash from \"~git-hash\";\n\nimport { Logger } from \"./Logger\";\nimport { relaunch } from \"./native\";\nimport { IpcRes } from \"./types\";\n\nexport const UpdateLogger = /* #__PURE__*/ new Logger(\"Updater\", \"white\");\nexport let isOutdated = false;\nexport let isNewer = false;\nexport let updateError: any;\nexport let changes: Record<\"hash\" | \"author\" | \"message\", string>[];\n\nasync function Unwrap<T>(p: Promise<IpcRes<T>>) {\n    const res = await p;\n\n    if (res.ok) return res.value;\n\n    updateError = res.error;\n    throw res.error;\n}\n\nexport async function checkForUpdates() {\n    changes = await Unwrap(VencordNative.updater.getUpdates());\n\n    // we only want to check this for the git updater, not the http updater\n    if (!IS_STANDALONE) {\n        if (changes.some(c => c.hash === gitHash)) {\n            isNewer = true;\n            return (isOutdated = false);\n        }\n    }\n\n    return (isOutdated = changes.length > 0);\n}\n\nexport async function update() {\n    if (!isOutdated) return true;\n\n    const res = await Unwrap(VencordNative.updater.update());\n\n    if (res) {\n        isOutdated = false;\n        if (!await Unwrap(VencordNative.updater.rebuild()))\n            throw new Error(\"The Build failed. Please try manually building the new update\");\n    }\n\n    return res;\n}\n\nexport const getRepo = () => Unwrap(VencordNative.updater.getRepo());\n\nexport async function maybePromptToUpdate(confirmMessage: string, checkForDev = false) {\n    if (IS_WEB || IS_UPDATER_DISABLED) return;\n    if (checkForDev && IS_DEV) return;\n\n    try {\n        const isOutdated = await checkForUpdates();\n        if (isOutdated) {\n            const wantsUpdate = confirm(confirmMessage);\n            if (wantsUpdate && isNewer) return alert(\"Your local copy has more recent commits. Please stash or reset them.\");\n            if (wantsUpdate) {\n                await update();\n                relaunch();\n            }\n        }\n    } catch (err) {\n        UpdateLogger.error(err);\n        alert(\"That also failed :( Try updating or re-installing with the installer!\");\n    }\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nimport { maybePromptToUpdate } from \"@utils/updater\";\n\nexport function handleComponentFailed() {\n    maybePromptToUpdate(\n        \"Uh Oh! Failed to render this Page.\" +\n        \" However, there is an update available that might fix it.\" +\n        \" Would you like to update and restart now?\"\n    );\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2023 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nexport function onlyOnce<F extends Function>(f: F): F {\n    let called = false;\n    let result: any;\n    return function onlyOnceWrapper(this: unknown) {\n        if (called) return result;\n\n        called = true;\n\n        return (result = f.apply(this, arguments));\n    } as unknown as F;\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2023 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nimport { BaseText } from \"@components/BaseText\";\nimport ErrorBoundary from \"@components/ErrorBoundary\";\nimport { handleComponentFailed } from \"@components/handleComponentFailed\";\nimport { Margins } from \"@utils/margins\";\nimport { onlyOnce } from \"@utils/onlyOnce\";\nimport type { ComponentType, PropsWithChildren } from \"react\";\n\nexport function SettingsTab({ title, children }: PropsWithChildren<{ title: string; }>) {\n    return (\n        <section>\n            <BaseText tag=\"h2\" size=\"xl\" weight=\"semibold\" className={Margins.bottom16}>{title}</BaseText>\n            {children}\n        </section>\n    );\n}\n\nexport const handleSettingsTabError = onlyOnce(handleComponentFailed);\n\nexport function wrapTab(component: ComponentType<any>, tab: string) {\n    return ErrorBoundary.wrap(component, {\n        message: `Failed to render the ${tab} tab. If this issue persists, try using the installer to reinstall!`,\n        onError: handleSettingsTabError,\n    });\n}\n", "/*\n * Vencord, a Discord client mod\n * Copyright (c) 2023 Vendicated and contributors\n * SPDX-License-Identifier: GPL-3.0-or-later\n */\n\nimport { findByPropsLazy } from \"@webpack\";\nimport { Parser } from \"@webpack/common\";\n\nconst CodeContainerClasses = findByPropsLazy(\"markup\", \"codeContainer\");\n\n/**\n * Renders code in a Discord codeblock\n */\nexport function CodeBlock(props: { content?: string, lang: string; }) {\n    return (\n        <div className={CodeContainerClasses.markup}>\n            {Parser.defaultRules.codeBlock.react(props, null, {})}\n        </div>\n    );\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\n/**\n * Returns a new function that will call the wrapped function\n * after the specified delay. If the function is called again\n * within the delay, the timer will be reset.\n * @param func The function to wrap\n * @param delay The delay in milliseconds\n */\nexport function debounce<T extends Function>(func: T, delay = 300): T {\n    let timeout: NodeJS.Timeout;\n    return function (...args: any[]) {\n        clearTimeout(timeout);\n        timeout = setTimeout(() => { func(...args); }, delay);\n    } as any;\n}\n", "/*\n * Vencord, a modification for Discord's desktop app\n * Copyright (c) 2022 Vendicated and contributors\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\n*/\n\nimport { moment } from \"@webpack/common\";\n\n// Utils for readable text transformations eg: `toTitle(fromKebab())`\n\n// Case style to words\nexport const wordsFromCamel = (text: string) =>\n    text.split(/(?=[A-Z][a-z])|(?<=[a-z])(?=[A-Z])/).map(w => /^[A-Z]{2,}$/.test(w) ? w : w.toLowerCase());\nexport const wordsFromSnake = (text: string) => text.toLowerCase().split(\"_\");\nexport const wordsFromKebab = (text: string) => text.toLowerCase().split(\"-\");\nexport const wordsFromPascal = (text: string) => text.split(/(?=[A-Z])/).map(w => w.toLowerCase());\nexport const wordsFromTitle = (text: string) => text.toLowerCase().split(\" \");\n\n// Words to case style\nexport const wordsToCamel = (words: string[]) =>\n    words.map((w, i) => (i ? w[0].toUpperCase() + w.slice(1) : w)).join(\"\");\nexport const wordsToSnake = (words: string[]) => words.join(\"_\").toUpperCase();\nexport const wordsToKebab = (words: string[]) => words.join(\"-\").toLowerCase();\nexport const wordsToPascal = (words: string[]) =>\n    words.map(w => w[0].toUpperCase() + w.slice(1)).join(\"\");\nexport const wordsToTitle = (words: string[]) =>\n    words.map(w => w[0].toUpperCase() + w.slice(1)).join(\" \");\n\nconst units = [\"years\", \"months\", \"weeks\", \"days\", \"hours\", \"minutes\", \"seconds\"] as const;\ntype Units = typeof units[number];\n\nfunction getUnitStr(unit: Units, isOne: boolean, short: boolean) {\n    if (shor